head.script:
/*
 * WAEA-967 검증 샘플 - Pivot pivotExcelDownload dialogTitle
 *
 * [엔진 전송 구조]
 *   pivotExcelDownload(options) 내부에서
 *     - dialogTitle 정규화: 값이 있으면 String으로, undefined/null/"" 이면 delete
 *     - sheetInfo.options = options  ->  JSON.stringify  ->  pivotToExcel.wq 로 POST
 *   즉 전송 payload JSON의 options.dialogTitle 위치로 전달된다.
 *
 * [Gear 없이 검증하는 방법]
 *   Gear 에이전트는 실물 환경이 없으면 Dialog Title 표시를 확인할 수 없다.
 *   대신 이 샘플은 getPivotSheetData(options) 를 감싸 "실제 전송 직전의 정규화된 options"를
 *   가로채 로그로 출력한다. 여기서 dialogTitle 키의 존재 여부/타입/값을 확인하면
 *   엔진 몫(요청 데이터 전달)은 검증된다. Dialog 표시 자체는 고객사 Gear 환경 몫.
 *
 * [주의] 버튼을 누르면 실제 pivotToExcel.wq 요청이 함께 발생한다.
 */
scwin.captured = null;

scwin.onpageload = function() {
    dataList1.setJSON([
        { region:"서울", industry:"제조",   amount:100 },
        { region:"서울", industry:"서비스", amount:30  },
        { region:"부산", industry:"제조",   amount:200 },
        { region:"부산", industry:"서비스", amount:70  }
    ]);
    scwin.installCapture();
};

// 전송 직전 정규화된 options 를 가로챈다.
scwin.installCapture = function() {
    if (typeof pivotTable1.getPivotSheetData !== "function") {
        scwin.log("[전제 실패] pivotTable1.getPivotSheetData 미제공. 엔진 구조가 달라 캡처 불가.");
        scwin.log("  -> 개발자도구 Network 탭에서 pivotToExcel 요청 payload를 직접 확인하세요.");
        return;
    }
    var original = pivotTable1.getPivotSheetData;
    pivotTable1.getPivotSheetData = function(options) {
        scwin.captured = options;
        return original.apply(this, arguments);
    };
    scwin.log("payload 캡처 준비 완료. 1~6번 버튼을 눌러 결과를 확인하세요.");
    scwin.log("(버튼 클릭 시 실제 pivotToExcel.wq 다운로드 요청도 함께 발생합니다)");
    scwin.log("");
};

scwin.log = function(msg) {
    txtLog.setValue(txtLog.getValue() + msg + "\n");
};

// options 를 넘겨 다운로드를 실행하고, 캡처된 dialogTitle 상태를 기대값과 함께 출력한다.
scwin.run = function(step, options, expectPresent, expectValue) {
    scwin.captured = null;
    try {
        pivotTable1.pivotExcelDownload(options);
    } catch (e) {
        scwin.log("[" + step + "] 호출 예외: " + (e && e.message ? e.message : String(e)));
        return;
    }

    var opts = scwin.captured;
    if (!opts) {
        scwin.log("[" + step + "] FAIL - options 캡처 실패 (getPivotSheetData 미호출)");
        return;
    }

    var present = Object.prototype.hasOwnProperty.call(opts, "dialogTitle");
    var actualValue = present ? opts.dialogTitle : "(키 없음)";
    var actualType = present ? typeof opts.dialogTitle : "-";

    var pass = (present === expectPresent) && (!expectPresent || (actualValue === expectValue && actualType === "string"));

    scwin.log("[" + step + "] " + (pass ? "PASS" : "FAIL"));
    scwin.log("  전달 위치 : payload JSON 의 options.dialogTitle");
    scwin.log("  키 존재   : " + present + " (기대 " + expectPresent + ")");
    scwin.log("  값        : " + JSON.stringify(actualValue) + " / typeof=" + actualType);
    if (expectPresent) {
        scwin.log("  기대 값   : " + JSON.stringify(expectValue) + " / typeof=string");
    }
    scwin.log("");
};

// 1) 기본 - 문자열 지정
scwin.btn1 = function() {
    scwin.run("1 기본 문자열",
        { fileName:"WAEA_967_1.xlsx", dialogTitle:"저장할 위치를 선택하세요" },
        true, "저장할 위치를 선택하세요");
};

// 2) 미지정 - 하위호환 (키 자체가 없어야 함)
scwin.btn2 = function() {
    scwin.run("2 미지정",
        { fileName:"WAEA_967_2.xlsx" },
        false);
};

// 3) 특수문자 - 이스케이프 없이 원문 유지
scwin.btn3 = function() {
    var v = "A&B <저장> \"경로\" '선택'";
    scwin.run("3 특수문자", { fileName:"WAEA_967_3.xlsx", dialogTitle:v }, true, v);
};

// 4) falsy 숫자 0 - 삭제되지 않고 문자열 "0" 으로 정규화되어야 함
scwin.btn4 = function() {
    scwin.run("4 falsy 숫자 0",
        { fileName:"WAEA_967_4.xlsx", dialogTitle:0 },
        true, "0");
};

// 5) 빈 문자열 - 키 삭제 (하위호환)
scwin.btn5 = function() {
    scwin.run("5 빈 문자열",
        { fileName:"WAEA_967_5.xlsx", dialogTitle:"" },
        false);
};

// 6) null - 키 삭제 (하위호환)
scwin.btn6 = function() {
    scwin.run("6 null",
        { fileName:"WAEA_967_6.xlsx", dialogTitle:null },
        false);
};

scwin.btnClear = function() {
    txtLog.setValue("");
};
